const MOD = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k, l int
	fmt.Fscan(in, &n, &k, &l)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int, maxN+1)
	invFact := make([]int, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invFact[maxN] = pow(fact[maxN], MOD-2, MOD)
	for i := maxN - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2 and their inverses
	pow2 := make([]int, maxN+1)
	invPow2 := make([]int, maxN+1)
	pow2[0] = 1
	for i := 1; i <= maxN; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}
	inv2 := pow(2, MOD-2, MOD)
	invPow2[0] = 1
	for i := 1; i <= maxN; i++ {
		invPow2[i] = invPow2[i-1] * inv2 % MOD
	}

	// Compute the answer
	ans := 0
	for i := 0; i <= n; i++ {
		// C(n, i) * C(n, i) * i! * (2n - i)! / (2n)! * (2n - 2i)! / 2^(2n - 2i)
		// Wait, let's use the formula from the analysis
		// term = C(n, i)^2 * i! * (2n - i)! / (2n)! * (2n - 2i)! / 2^(2n - 2i)
		// But we need to compute this modulo MOD
		// Let's compute it step by step
		// C(n, i) = fact[n] * invFact[i] * invFact[n-i] % MOD
		c := fact[n] * invFact[i] % MOD * invFact[n-i] % MOD
		c2 := c * c % MOD
		// i!
		f := fact[i]
		// (2n - i)!
		f2 := fact[2*n-i]
		// (2n)!
		f3 := fact[2*n]
		// (2n - 2i)!
		f4 := fact[2*n-2*i]
		// 2^(2n - 2i)
		p := pow2[2*n-2*i]
		// inv(2^(2n - 2i))
		invP := invPow2[2*n-2*i]

		// term = c2 * f * f2 * inv(f3) * f4 * invP
		term := c2 * f % MOD
		term = term * f2 % MOD
		term = term * invFact[2*n] % MOD
		term = term * f4 % MOD
		term = term * invP % MOD

		// Multiply by (2n - 2i + 1)
		term = term * (2*n - 2*i + 1) % MOD

		// Add to answer if i >= k
		if i >= k {
			ans = (ans + term) % MOD
		}
	}

	// Multiply by l
	ans = ans * l % MOD

	fmt.Println(ans)
}

func pow(a, b, mod int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
