const MOD = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	var l int64
	fmt.Fscan(in, &n, &k, &l)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int, maxN+1)
	invFact := make([]int, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invFact[maxN] = pow(fact[maxN], MOD-2, MOD)
	for i := maxN - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2 inverse
	inv2 := (MOD + 1) / 2
	inv2Pow := make([]int, maxN+1)
	inv2Pow[0] = 1
	for i := 1; i <= maxN; i++ {
		inv2Pow[i] = inv2Pow[i-1] * inv2 % MOD
	}

	// Compute the answer
	ans := 0
	for m := k; m <= n; m++ {
		// C(n, m) * C(2n - m, n) * inv2^(2n - m) * (m / (2n + 1))
		cnm := comb(n, m, fact, invFact)
		c2nm := comb(2*n-m, n, fact, invFact)
		pow2 := inv2Pow[2*n - m]
		term := cnm * c2nm % MOD
		term = term * pow2 % MOD
		term = term * m % MOD
		term = term * pow(2*n+1, MOD-2, MOD) % MOD
		ans = (ans + term) % MOD
	}

	// Multiply by l and by (2n + 1)
	ans = ans * l % MOD
	ans = ans * (2*n + 1) % MOD

	fmt.Println(ans)
}

func comb(n, k int, fact, invFact []int) int {
	if k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD
}

func pow(a, b, mod int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}
